-- SEED DEMO v2 · Estúdio Aurora · schema single-tenant real

on conflict (id) do nothing;
update whatsapp_hub.ai_agent_config set
  system_prompt = 'Você é a assistente do Estúdio Aurora. Tom da casa: direto, cordial, sem infantilizar. Regras: desconto máximo 10% à vista, prazo mínimo 30 dias, entrada de 50%. Nunca prometa o que não está na tabela.',
  temperature = 0.4, is_active = true
where id is not null;